import { useAnalytics, useCoreContext, useCommonContext } from "@/providers";
import { useCallback, useState, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import { useChatByIdApi } from "./api/chats";
import { Message } from "@/lib/types";
import { v4 as uuidv4 } from 'uuid';
import { useOwnedBundlesApi } from "@/hooks/api/bundles";

// this message is used to start the chat from the AI side
// this should be a dynamic message that is generated by the AI
// this should contain buttons for the different exams
const fakeStartMessage: Message = {
  messageUuid: '',
  chatUuid: '',
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  role: 'assistant',
  content: `### Practice Tests

Pick a subject or exam and how many questions you want.

**Examples**
- **Geometry** — \`Geometry, 10 questions\`
- **GRE Quantitative** — \`GRE Quant, 6 questions\`
- **World Capitals** — \`World capitals, 8 questions\`
- **Biology (Genetics)** — \`Genetics, 6 questions\`
- **Harry Potter Spells** — \`Harry Potter spells, 7 questions\`
- **Pokémon Types** — \`Pokemon type matchups, 5 questions\`
`};

export const useMockExamChat = () => {
  const { ownedModules } = useOwnedBundlesApi();
  const { waitingFor } = useCoreContext();
  const [AIFirstMessageSent, setAIFirstMessageSent] = useState(false);
  const { isMobile } = useCommonContext();
  const [fakeStartMessages, setFakeStartMessages] = useState<Message[]>([]);
  const [bubbleSuggestions, setBubbleSuggestions] = useState<Array<{ label: string; message: string; send?: boolean; disabled?: boolean }>>([]);
  const [selection, setSelection] = useState<{ subjectOrExam?: string; questionCount?: number }>({});
  const [chatUuid] = useState<string>(uuidv4());
  const [loadingQuizPage, setLoadingQuizPage] = useState(false);
  const { track } = useAnalytics();
  const router = useRouter();
  const [isPaidPlanModalOpen, setIsPaidPlanModalOpen] = useState(false);

  const suggestionsMobile = useMemo(() => [
    { label: 'Geometry', message: 'I want a Geometry practice test', send: false },
    { label: 'GRE Quantitative', message: 'I want a GRE Quantitative practice test', send: false },
    { label: 'World Capitals', message: 'I want a World Capitals practice test', send: false },
  ], []);

  const suggestionsDesktop = useMemo(() => [
    { label: 'Geometry', message: 'I want a Geometry practice test', send: false },
    { label: 'GRE Quantitative', message: 'I want a GRE Quantitative practice test', send: false },
    { label: 'World Capitals', message: 'I want a World Capitals practice test', send: false },
    { label: 'Biology (Genetics)', message: 'I want a Biology (Genetics) practice test', send: false },
    { label: 'Harry Potter Spells', message: 'I want a Harry Potter spells practice test', send: false },
  ], []);

  useEffect(() => {
    if (!AIFirstMessageSent) {
      setTimeout(() => {
        setFakeStartMessages([fakeStartMessage]);
        setAIFirstMessageSent(true);
      }, 1000);

      setTimeout(() => {
        setBubbleSuggestions(isMobile ? suggestionsMobile : suggestionsDesktop);
      }, 2000);
    }
  }, [AIFirstMessageSent, isMobile, suggestionsMobile, suggestionsDesktop]);

  const handleSuggestionUsed = useCallback(({ label, message, send, showPricingModal }: { label: string; message: string; send: boolean, showPricingModal?: boolean }) => {
    if (showPricingModal) {
      // open modal to show the pricing plans
      setIsPaidPlanModalOpen(true);
      return;
    }

    track('mock_exam_suggestion_clicked', { label, message });
    if (!selection.subjectOrExam) {
      setSelection(s => ({ ...s, subjectOrExam: label }));
      // move to question count suggestions
      setBubbleSuggestions([
        { label: '3 Qs', message: `${message}, 3 questions`, send: false },
        { label: '5 Qs', message: `${message}, 5 questions`, send: false },
        { label: '10 Qs', message: `${message}, 10 questions`, send: false },
      ]);
      return;
    }

    setBubbleSuggestions([]);
  }, [selection]);

  const { 
    isLoading: isChatsLoading, messages, chat,
    localTempMessage, setLocalTempMessage, sendMessage, 
    hasMoreMessages, loadMore } = useChatByIdApi(
    { 
      chatUuid: chatUuid,
      chatType: 'mock_exam',
      chatArgs: {
        chatUuid: chatUuid,
      },
    });

  const handleCreatedMockExam = useCallback(({ mockExamUuid }: { mockExamUuid: string }) => {
    track('mock_exam_created', { mockExamUuid });
    setLoadingQuizPage(true);
    router.push(`/mock-exam/${mockExamUuid}`);
  }, [track, router]);

  return {
    chatUuid,
    loadingQuizPage,
    messages: fakeStartMessages.concat(messages),
    localTempMessage,
    setLocalTempMessage,
    sendMessage,
    isChatsLoading,
    waitingFor,
    hasMoreMessages,
    loadMore,
    bubbleSuggestions,
    handleSuggestionUsed,
    handleCreatedMockExam,
    isPaidPlanModalOpen,
    setIsPaidPlanModalOpen,
  };
};